INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(32711, 'Mark 8:16', 'Mark', 8, 16, 'نو شاګردانو په خپل منځ کې سره بحث پیل کړ او ویې ویل: «هغه ځکه دا خبره کوي چې زمونږ سره ډوډۍ نشته.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_16.mp3', '', 1761754199, 1761754199),
(32712, 'Mark 8:17', 'Mark', 8, 17, 'عیسی پوه شو چې هغوی څه وایي، نو د هغوی څخه یې پوښتنه وکړه: «تاسو ولې په دې هکله بحث کوئ چې ډوډۍ درسره نشته؟ ایا تاسو تر‌اوسه خبر نه یئ او نه پوهېږئ؟ ایا ستاسو زړونه سخت شوي دي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_17.mp3', '', 1761754199, 1761754199),
(32713, 'Mark 8:18', 'Mark', 8, 18, 'تاسو سترګې لرئ خو لیدلی نه شئ او غوږونه لرئ خو اورېدلی نه شئ؟ ایا تاسو ته په یاد نه دي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_18.mp3', '', 1761754199, 1761754199),
(32714, 'Mark 8:19', 'Mark', 8, 19, 'چې کله ما پنځه ډوډۍ په پنځه زره کسانو ووېشلې، نو تاسو د هغې ډوډۍ د پاتې شویو ټوټو څخه څو ټوکرۍ ډکې کړې؟» هغوی وویل: «دولس ټوکرۍ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_19.mp3', '', 1761754199, 1761754199),
(32715, 'Mark 8:20', 'Mark', 8, 20, 'نو عیسی پوښتنه وکړه: «چې کله مې اووه ډوډۍ په څلورو زرو کسانو ووېشلې، د هغو د پاتې شویو ټوټو څخه مو څو ټوکرۍ ډکې کړې؟» هغوی وویل: «اووه ټوکرۍ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_20.mp3', '', 1761754199, 1761754199),
(32716, 'Mark 8:21', 'Mark', 8, 21, 'نو عیسی وویل: «تاسو لا تر‌اوسه هم نه پوهېږئ؟» عیسی په بیت‌صیدا کې یو ړوند ته شفا ورکوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_21.mp3', '', 1761754199, 1761754199),
(32717, 'Mark 8:22', 'Mark', 8, 22, 'عیسی او شاګردان یې بیت‌صیدا ته ورسېدل. هلته ځینو خلکو عیسی ته یو ړوند سړی راوست او هغه ته یې زاري وکړه چې په هغه باندې خپل لاس کېږدي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_22.mp3', '', 1761754199, 1761754199),
(32718, 'Mark 8:23', 'Mark', 8, 23, 'عیسی هغه ړوند له لاسه ونیوه او د کلي څخه یې دباندې بوته. بیا یې د هغه په سترګو باندې لاړې پورې کړې او خپل لاسونه یې ورباندې کېښودل او پوښتنه یې ترې وکړه: «ایا څه شی وینې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_23.mp3', '', 1761754199, 1761754199),
(32719, 'Mark 8:24', 'Mark', 8, 24, 'د هغه سترګې بینا شوې او ویې ویل: «هو، زه خلک وینم چې ګرځي او راګرځي، خو هغوی راته د ونو په شان ښکاري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_24.mp3', '', 1761754199, 1761754199),
(32720, 'Mark 8:25', 'Mark', 8, 25, 'عیسی یوځل بیا د هغه په سترګو باندې خپل لاسونه کېښودل او هغه بیخي بینا شو، د سترګو نظر یې بېرته جوړ شو او هرڅه یې ښه لیدلی شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_25.mp3', '', 1761754199, 1761754199),
(32721, 'Mark 8:26', 'Mark', 8, 26, 'عیسی هغه خپل کور ته رخصت کړ او ورته ویې ویل: «ته کولای شې چې بېرته خپل کور ته لاړ شې، خو په کلي کې مه ګرځه.» د عیسی په هکله د پطروس اقرار (متي ۱۶‏:‌۱۳‌‏-‌۲۰ او لوقا ۹‏:‌۱۸‌‏-‌۲۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_26.mp3', '', 1761754199, 1761754199),
(32722, 'Mark 8:27', 'Mark', 8, 27, 'بیا عیسی او شاګردان یې د قیصریې فیلیپوس شاوخوا کلیو ته لاړل. هغه په لاره کې د خپلو شاګردانو څخه پوښتنه وکړه: «خلک څه وایي چې زه څوک یم؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_27.mp3', '', 1761754199, 1761754199),
(32723, 'Mark 8:28', 'Mark', 8, 28, 'هغوی ځواب ورکړ: «ځینې وایي چې ته تعمید ورکوونکی یحیی یې، ځینې وایي چې الیاس نبي یې او نور وایي چې د پیغمبرانو څخه یو پیغمبر یې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_28.mp3', '', 1761754199, 1761754199),
(32724, 'Mark 8:29', 'Mark', 8, 29, 'بیا عیسی پوښتنه وکړه: «تاسو څه وایئ چې زه څوک یم؟» پطروس ځواب ورکړ: «ته مسیح یې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_29.mp3', '', 1761754199, 1761754199),
(32725, 'Mark 8:30', 'Mark', 8, 30, 'بیا عیسی هغوی ته په کلکه حکم وکړ چې د هغه په هکله دې هېچا ته څه ونه وایي. عیسی د خپلو کړاوونو او مرګ په هکله پېشګویي کوي (متي ۱۶‏:‌۲۱‌‏-‌۲۸ او لوقا ۹‏:‌۲۲‌‏-‌۲۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_30.mp3', '', 1761754199, 1761754199),
(32726, 'Mark 8:31', 'Mark', 8, 31, 'بیا عیسی خپلو شاګردانو ته تعلیم ورکول پیل کړ چې د انسان زوی به خامخا زیات کړاوونه وزغمي او د یهودیانو د مشرانو، مشرانو کاهنانو او د شریعت د عالمانو له خوا به رد کړای شي او وبه وژل شي او په درېمه ورځ به بیا راژوندی شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_31.mp3', '', 1761754199, 1761754199),
(32727, 'Mark 8:32', 'Mark', 8, 32, 'هغه په دې هکله ښکاره خبرې وکړې. نو پطروس هغه ګوښه کړ او د داسې خبرو نه یې منع کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_32.mp3', '', 1761754199, 1761754199),
(32728, 'Mark 8:33', 'Mark', 8, 33, 'خو عیسی مخ راواړاوه او خپلو شاګردانو ته یې وکتل او پطروس یې ورټلو او ورته ویې ویل: «زما له مخې نه لېرې شه شیطانه! ته د انسانانو په شان فکر کوې، نه د خدای په شان.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_33.mp3', '', 1761754199, 1761754199),
(32729, 'Mark 8:34', 'Mark', 8, 34, 'بیا عیسی خلک او خپل شاګردان راوغوښتل او هغوی ته یې وویل: «که څوک وغواړي چې زما د پیروانو څخه اوسي، نو باید د خپل ځان څخه تېر شي، خپل صلیب دې راواخلي او ما پسې دې راځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_34.mp3', '', 1761754199, 1761754199),
(32730, 'Mark 8:35', 'Mark', 8, 35, 'ځکه څوک چې وغواړي خپل ځان وساتي نو هغه به له لاسه ورکړي، خو که څوک زما او زما د زېري په خاطر خپل ژوند له لاسه ورکړي، نو هغه به وژغوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_35.mp3', '', 1761754199, 1761754199),
(32731, 'Mark 8:36', 'Mark', 8, 36, 'د یو چا دپاره به څه ګټه وي چې ټوله نړۍ لاسته راوړي خو خپل ځان له لاسه ورکړي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_36.mp3', '', 1761754199, 1761754199),
(32732, 'Mark 8:37', 'Mark', 8, 37, 'انسان د خپل ژوند په بدل کې څه شی ورکولای شي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_37.mp3', '', 1761754199, 1761754199),
(32733, 'Mark 8:38', 'Mark', 8, 38, 'که چېرې څوک په دې بې‌ایمانه او ګناهکاره زمانه کې په ما او یا زما په کلام شرمیږي، نو د انسان زوی به هم کله چې د خپل پلار په جلال کې د سپېڅلو فرښتو سره راځي، په هغه وشرمیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_38.mp3', '', 1761754199, 1761754199),
(32734, 'Romans 5:1', 'Romans', 5, 1, 'له دې امله چې مونږ د ایمان په وسیله عادل ګڼل شوي یو، نو زمونږ د څښتن عیسی مسیح په وسیله د خدای سره زمونږ روغه جوړه وشوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_1.mp3', '', 1761754199, 1761754199),
(32735, 'Romans 5:2', 'Romans', 5, 2, 'د هغه په وسیله او د خپل ایمان له لارې د خدای په دې تجربه شوي فضل هغه ځای مونږ ته راکړل شو چې اوس په کې اوسېږو او په دې هیله خوشحالي کوو چې د خدای په جلال کې به شریک شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_2.mp3', '', 1761754199, 1761754199),
(32736, 'Romans 5:3', 'Romans', 5, 3, 'یوازې په دې شیانو نه، بلکې په خپلو کړاوونو او تکلیفونو باندې هم خوشحالي کوو، ځکه مونږ پوهېږو چې تکلیفونه صبر او زغم راپیدا کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_3.mp3', '', 1761754199, 1761754199),
(32737, 'Romans 5:4', 'Romans', 5, 4, 'صبر او زغم د دې سبب ګرځي چې مونږ خدای ته د منلو وړ وګرځو او دا کار هیله راپیدا کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_4.mp3', '', 1761754199, 1761754199),
(32738, 'Romans 5:5', 'Romans', 5, 5, 'دا هیله مونږ هېڅکله شرمېدلو ته نه پرېږدي، ځکه چې د خدای مینه د روح القدس په وسیله چې مونږ ته راکړل شوی ده، زمونږ په زړونو کې اچول شوې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_5.mp3', '', 1761754199, 1761754199),
(32739, 'Romans 5:6', 'Romans', 5, 6, 'کله چې هغه وخت مونږ لا بې‌وسه وو، نو مسیح په ټاکل شوي وخت کې د ګناهکارانو دپاره مړ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_6.mp3', '', 1761754199, 1761754199),
(32740, 'Romans 5:7', 'Romans', 5, 7, 'داسې یو څوک به ډېر کم پیدا شي چې حتی د یو عادل سړي دپاره خپل ځان له لاسه ورکړي. خو کېدای شي چې یو څوک جرات وکړي چې د یو مهربانه سړي دپاره خپل ځان قربان کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_7.mp3', '', 1761754199, 1761754199),
(32741, 'Romans 5:8', 'Romans', 5, 8, 'خو خدای خپله مینه مونږ ته داسې وښودله چې هغه وخت چې مونږ لا ګناهکاران وو، مسیح زمونږ دپاره مړ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_8.mp3', '', 1761754199, 1761754199),
(32742, 'Romans 5:9', 'Romans', 5, 9, 'اوس چې مونږ د هغه د وینې په وسیله عادل ګڼل شوي یو، نو مونږ به څومره نور هم د هغه په وسیله د خدای د غضب څخه وژغورل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_9.mp3', '', 1761754199, 1761754199),
(32743, 'Romans 5:10', 'Romans', 5, 10, 'ځکه کله چې مونږ د خدای دښمنان وو، نو د هغه د زوی د مرګ په وسیله ورسره پخلا شو، نو اوس چې مونږ سره پخلا شوي یو، نو څومره زیات به د مسیح ژوند زمونږ د خلاصون سبب وګرځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_10.mp3', '', 1761754199, 1761754199),
(32744, 'Romans 5:11', 'Romans', 5, 11, 'خو یوازې دا نه، بلکې مونږ د خپل څښتن عیسی مسیح په وسیله چې اوس یې مونږ د خدای سره پخلا کړي یو، په خدای کې خوشحالي کوو. د ادم ګناه او د مسیح فضل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_11.mp3', '', 1761754199, 1761754199),
(32745, 'Romans 5:12', 'Romans', 5, 12, 'لکه څنګه چې ګناه د یو انسان په وسیله نړۍ ته راغله او د ګناه په وسیله مرګ راغی، نو په دې ډول مرګ ټولو انسانانو ته راغی، ځکه چې ټولو ګناه وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_12.mp3', '', 1761754199, 1761754199),
(32746, 'Romans 5:13', 'Romans', 5, 13, 'ګناه د شریعت نه مخکې په دنیا کې موجوده وه، خو چېرته چې شریعت نه وي، نو څوک ګناهکار نه ګڼل کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_13.mp3', '', 1761754199, 1761754199),
(32747, 'Romans 5:14', 'Romans', 5, 14, 'خو سره له دې مرګ په هغو خلکو باندې هم چې د ادم د زمانې نه د موسی تر زمانې پورې يې ژوند کړی دی، حتی په هغو خلکو باندې هم چې د ادم په شان یې د خدای د حکم نه سرغړونه نه وه کړې، حاکم ؤ. ادم د هغه چا یو مثال او نښه ؤ چې راتلونکی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_14.mp3', '', 1761754199, 1761754199),
(32748, 'Romans 5:15', 'Romans', 5, 15, 'خو د ادم د سرغړونې او د خدای د وړیا فضل تر منځ زیات فرق دی. ځکه د یو انسان یعنې د ادم د سرغړونې له امله ډېر خلک مړه شول، خو د خدای فضل او بخښنه څومره لویه ده او د هغه وړیا نعمت چې د یو بل انسان یعنې عیسی مسیح د فضل په وسیله ډېرو ته ورکړ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_15.mp3', '', 1761754199, 1761754199),
(32749, 'Romans 5:16', 'Romans', 5, 16, 'د ادم د ګناه د نتیجې او د خدای د نعمت تر منځ زیات فرق دی. ځکه چې د هغې ګناه په هکله قضاوت د محکوم کېدلو سبب کیږي، خو د خدای نعمت زمونږ دپاره دا امکان برابروي چې د هغه دپاره عادل وګڼل شو، که څه هم مونږ ډېر ځلې سرغړونې کړې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_16.mp3', '', 1761754199, 1761754199),
(32750, 'Romans 5:17', 'Romans', 5, 17, 'که چېرې د یو انسان د سرغړونې له امله مرګ په انسان باندې حاکم شو، نو د هغه کار نتیجه به څومره لویه وي چې هغه بل انسان یعنې عیسی مسیح سرته ورساوه. هغو ټولو خلکو چې د عیسی پرېمانه فضل او د عدالت وړیا نعمت یې تر‌لاسه کړ، د مسیح په وسیله به په ژوند کې لکه د پاچاهانو په شان حکومت کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_17.mp3', '', 1761754199, 1761754199),
(32751, 'Romans 5:18', 'Romans', 5, 18, 'نو لکه څنګه چې یوه سرغړونه د ټولو خلکو د محکوم کېدلو سبب شوې ده، نو په همدې ډول یو نېک عمل ټول عادلان ګڼلي دي او ژوند یې ورکړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_18.mp3', '', 1761754199, 1761754199),
(32752, 'Romans 5:19', 'Romans', 5, 19, 'لکه څنګه چې د یو سړي د نافرمانۍ له امله ډېر خلک ګناهکار شول، نو په همدې ډول به ډېر خلک د یو سړي د فرمانبردارۍ په وسیله عادلان وګڼل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans5_verse_19.mp3', '', 1761754199, 1761754199),
