(32799, 'Acts 7:4', 'Acts', 7, 4, 'نو ابراهیم د کلدانیانو د وطن څخه لاړ او په حاران کې اوسېده. کله چې د ابراهیم پلار مړ شو، نو خدای هغه دې وطن ته چې تاسو اوس په کې اوسېږئ، راوست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_4.mp3', '', 1761754199, 1761754199),
(32800, 'Acts 7:5', 'Acts', 7, 5, 'خو خدای په هغه وطن کې هغه ته حتی یو متر مربع ځمکه هم د میراث په توګه ورنه کړه، حتی دومره ځمکه یې هم ورنه کړه چې پښه ورباندې کېږدي. خو خدای وعده وکړه چې دا ځمکه به هغه ته او د هغه څخه وروسته د هغه اولادې ته ورکړي چې د هغوی ملکیت شي، که څه هم ابراهیم په هغه وخت کې اولاد نه درلود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_5.mp3', '', 1761754199, 1761754199),
(32801, 'Acts 7:6', 'Acts', 7, 6, 'نو خدای ابراهیم ته داسې وویل: ‹ستا اولاده به په پردي وطن کې د مسافرو په شان اوسیږي. هغوی به هلته غلامان وي او څلور سوه کاله به ورباندې ظلم کیږي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_6.mp3', '', 1761754199, 1761754199),
(32802, 'Acts 7:7', 'Acts', 7, 7, 'همدارنګه خدای وویل: ‹خو زه به هغه قوم ته چې ستاسو د اولادې څخه غلامان جوړوي، سزا ورکړم. وروسته به هغوی د هغه وطن څخه راووځي او په دې ځای کې به زما عبادت کوي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_7.mp3', '', 1761754199, 1761754199),
(32803, 'Acts 7:8', 'Acts', 7, 8, 'بیا خدای ابراهیم ته د سنتولو حکم ورکړ چې د لوظ یوه نښه به وي، ترڅو دا وښایي چې هغه په شوي لوظ باندې عمل کړی دی. نو کله چې د ابراهیم زوی اسحاق پیدا شو، نو هغه یې په اتمه ورځ سنت کړ. اسحاق خپل زوی یعقوب سنت کړ او یعقوب خپل دولس زامن چې وروسته بیا د دولسو قبیلو مشران شول، سنت کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_8.mp3', '', 1761754199, 1761754199),
(32804, 'Acts 7:9', 'Acts', 7, 9, 'د یعقوب زامنو د خپل ورور یوسف سره بخیلي پیدا کړه او هغه یې په مصر کې د غلام په توګه خرڅ کړ. خو خدای د هغه سره مل ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_9.mp3', '', 1761754199, 1761754199),
(32805, 'Acts 7:10', 'Acts', 7, 10, 'او هغه یې له خپلو ټولو تکلیفونو څخه خلاص کړ. کله چې یوسف د مصر د پاچا فرعون په حضور کې راښکاره شو، خدای په هغه باندې فضل وکړ او هغه ته یې حکمت ورکړ. نو فرعون هغه د ټول مصر واکمن او د خپلې کورنۍ مسوول وټاکه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_10.mp3', '', 1761754199, 1761754199),
(32806, 'Acts 7:11', 'Acts', 7, 11, 'بیا په ټول مصر او کنعان کې قحطي راغله چې د یو لوی مصیبت د رامنځته کېدلو سبب شوه او زمونږ نیکونو د خوراک دپاره څه شی نه شو پیدا کولای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_11.mp3', '', 1761754199, 1761754199),
(32807, 'Acts 7:12', 'Acts', 7, 12, 'نو کله چې یعقوب خبر شو چې په مصر کې غلې دانې پیدا کیږي، نو هغه خپل زامن یعنې زمونږ نیکونه د لومړي ځل دپاره هلته ولېږل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts7_verse_12.mp3', '', 1761754199, 1761754199),
